using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;
using Media=System.Windows.Controls.MediaElement;
static class PreviewPlaybackTests {
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Mouse(Control c,string method,int x){c.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,c.Height/2,0)});}
 [STAThread]static void Main(string[] args){PreviewProgram.File=Path.GetFullPath(args[0]);PreviewProgram.Check=Path.GetFullPath(args[1]);Directory.CreateDirectory(PreviewProgram.Check);Application.EnableVisualStyles();var form=new VideoPreview();form.Shown+=async(s,e)=>{try{var media=Field<Media>(form,"media");var slider=Field<ThemeSlider>(form,"seek");var state=Field<PreviewSeeking>(form,"seeking");for(int i=0;i<100&&!media.NaturalDuration.HasTimeSpan;i++)await Task.Delay(100);if(!media.NaturalDuration.HasTimeSpan)throw new Exception("Decoder did not open");int passed=0;foreach(double target in new[]{.75,.15,.6,.1,.8,.2}){Mouse(slider,"OnMouseDown",slider.Width*3/4);for(int j=0;j<30;j++)Mouse(slider,"OnMouseMove",(int)(slider.Width*(.8+(target-.8)*j/29)));Mouse(slider,"OnMouseUp",(int)(slider.Width*target));await Task.Delay(650);if(state.Pending||!state.Playing)throw new Exception("Seek did not settle");var before=media.Position.TotalSeconds;await Task.Delay(350);if(media.Position.TotalSeconds<before+.05)throw new Exception("Playback stopped advancing after seek");if(!media.IsMuted)throw new Exception("Seek lost explicit mute");passed++;}
 state.Toggle();Mouse(slider,"OnMouseDown",slider.Width/3);Mouse(slider,"OnMouseUp",slider.Width/3);await Task.Delay(650);double paused=media.Position.TotalSeconds;await Task.Delay(350);if(state.Playing||Math.Abs(media.Position.TotalSeconds-paused)>.05)throw new Exception("Paused seek unexpectedly played");passed++;File.WriteAllText(Path.Combine(PreviewProgram.Check,"seek-result.json"),"{\"ok\":true,\"checks\":"+passed+"}");}catch(Exception error){File.WriteAllText(Path.Combine(PreviewProgram.Check,"seek-result.json"),"{\"ok\":false,\"error\":\""+error.Message.Replace("\"","'")+"\"}");}finally{form.Close();}};Application.Run(form);}
}
